mapper.select:
SELECT COUNT(*)
FROM projection_inbox
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND consumer_name=#{consumer}
AND event_id=#{eventId}

SELECT event_id, aggregate_id, aggregate_version, event_type, payload, occurred_at
FROM projection_inbox
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND consumer_name=#{consumer}
AND aggregate_id=#{aggregateId}
AND aggregate_version=#{aggregateVersion}

SELECT id, live_generation, rebuild_generation, last_event_id, last_event_time, version
FROM projection_checkpoint
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND projection_name=#{name} FOR UPDATE

mapper.update:
UPDATE projection_checkpoint
SET live_generation=#{live}, rebuild_generation=#{rebuild}, last_event_id=#{eventId}, last_event_time=#{eventTime}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND projection_name=#{name}
AND version=#{version}

mapper.select:
SELECT id, source_version, on_hand_qty, reserved_qty, as_of
FROM inventory_view
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND generation=#{generation}
AND id=#{balanceId} FOR UPDATE

mapper.update:
UPDATE inventory_view
SET on_hand_qty=#{onHand}, reserved_qty=#{reserved}, source_version=#{sourceVersion}, as_of=#{asOf}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND generation=#{generation}
AND id=#{id}
AND source_version=#{expectedVersion}

mapper.insert:
INSERT INTO inventory_view (id, enterprise_id, warehouse_id, generation, owner_id, location_id, sku_id, lot_id, quality_code, on_hand_qty, reserved_qty, free_execution_claim_qty, source_version, as_of, eligible, version, created_at, updated_at) SELECT id, enterprise_id, warehouse_id, #{generation}, owner_id, location_id, sku_id, lot_id, quality_code, on_hand_qty, reserved_qty, free_execution_claim_qty, version, #{now}, 1, 0, #{now}, #{now}
FROM stock_balance
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}

mapper.select:
SELECT id, owner_id, location_id, sku_id, lot_id, quality_code, on_hand_qty, reserved_qty, free_execution_claim_qty, source_version, as_of, version
FROM inventory_view
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND generation=#{generation}
AND (#{skuId} IS NULL OR sku_id=#{skuId})
AND id > #{page.id}
ORDER BY id
LIMIT #{page.fetchLimit}

SELECT MAX(as_of) AS as_of
FROM inventory_view
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND generation=#{generation}

SELECT MAX(source_version) AS high_water
FROM inventory_view
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND generation=#{generation}
